{"file_path":"src/order.js","old_string":"  /**
   * Apply one command.
   *
   * @param {object} command Command to apply.
   * @returns {{ok: boolean, state: string, seq: number, replayed: boolean, code?: string, message?: string}} Outcome.
   */
  apply(command) {
    throw new Error('not implemented');
  }","new_string":"  /**
   * Apply one command.
   *
   * @param {object} command Command to apply.
   * @returns {{ok: boolean, state: string, seq: number, replayed: boolean, code?: string, message?: string}} Outcome.
   */
  apply(command) {
    // Structural validation
    if (typeof command !== 'object' || command === null) {
      throw new TypeError('command must be an object');
    }

    if (!COMMAND_TYPES.includes(command.type)) {
      throw new TypeError(`unknown command type: ${command.type}`);
    }

    if (typeof command.commandId !== 'string' || command.commandId === '') {
      throw new TypeError('command must carry a non-empty commandId');
    }

    if (!Number.isInteger(command.at) || command.at < 0) {
      throw new TypeError('command must carry a non-negative integer at');
    }

    // Check for replayed commandId
    if (this.#commandIds.has(command.commandId)) {
      const recorded = this.#commandIds.get(command.commandId);
      return {
        ...recorded,
        replayed: true,
      };
    }

    // Clock regression check and audit entry creation
    let auditAt = command.at;
    if (command.at < this.#clockMs) {
      auditAt = this.#clockMs;
    } else {
      this.#clockMs = command.at;
    }

    // Check if state allows this command
    const allowed = allowedTypes(this.#state);
    if (!allowed.includes(command.type)) {
      const entry = {
        seq: this.#audit.length + 1,
        commandId: command.commandId,
        type: command.type,
        at: auditAt,
        from: this.#state,
        to: this.#state,
        ok: false,
        code: 'BAD_STATE',
      };
      this.#audit.push(entry);

      const result = {
        ok: false,
        code: 'BAD_STATE',
        message: `state ${this.#state} does not allow ${command.type}`,
        state: this.#state,
        seq: entry.seq,
        replayed: false,
      };
      this.#commandIds.set(command.commandId, result);

      if (command.at < this.#clockMs) {
        return {
          ...result,
          code: 'CLOCK_REGRESSION',
          message: `command timestamp ${command.at} is earlier than clock ${this.#clockMs}`,
        };
      }

      return result;
    }

    // Field and business validations
    let validationError = null;
    let code = null;
    let message = null;

    // Validate command-specific fields
    switch (command.type) {
      case 'addItem': {
        if (typeof command.sku !== 'string' || command.sku === '') {
          code = 'MISSING_FIELD';
          message = 'addItem requires a non-empty sku';
        } else if (!Number.isInteger(command.qty) || command.qty < 1) {
          code = 'BAD_AMOUNT';
          message = 'addItem qty must be at least 1';
        } else if (!Number.isInteger(command.unitPriceCents) || command.unitPriceCents < 0) {
          code = 'BAD_AMOUNT';
          message = 'addItem unitPriceCents must be non-negative';
        } else if (this.#items.has(command.sku)) {
          code = 'DUPLICATE_SKU';
          message = `sku ${command.sku} is already in the order`;
        }
        break;
      }
      case 'removeItem': {
        if (typeof command.sku !== 'string' || command.sku === '') {
          code = 'MISSING_FIELD';
          message = 'removeItem requires a non-empty sku';
        } else if (!this.#items.has(command.sku)) {
          code = 'NO_SUCH_ITEM';
          message = `sku ${command.sku} is not in the order`;
        }
        break;
      }
      case 'pay': {
        if (!Number.isInteger(command.amountCents) || command.amountCents < 0) {
          code = 'BAD_AMOUNT';
          message = 'pay amountCents must be non-negative';
        } else if (this.totalCents === 0 && command.amountCents === 0) {
          code = 'EMPTY_ORDER';
          message = 'cannot pay for an empty order';
        } else if (command.amountCents !== this.totalCents) {
          code = 'AMOUNT_MISMATCH';
          message = `pay amount ${command.amountCents} does not match total ${this.totalCents}`;
        }
        break;
      }
      case 'ship': {
        if (typeof command.carrier !== 'string' || command.carrier === '') {
          code = 'MISSING_FIELD';
          message = 'ship requires a non-empty carrier';
        } else if (typeof command.tracking !== 'string' || command.tracking === '') {
          code = 'MISSING_FIELD';
          message = 'ship requires a non-empty tracking';
        }
        break;
      }
      case 'cancel': {
        if (typeof command.reason !== 'string' || command.reason === '') {
          code = 'MISSING_FIELD';
          message = 'cancel requires a non-empty reason';
        }
        break;
      }
      case 'refund': {
        if (!Number.isInteger(command.amountCents) || command.amountCents < 1) {
          code = 'BAD_AMOUNT';
          message = 'refund amountCents must be at least 1';
        } else if (command.amountCents > this.#paidCents - this.#refundedCents) {
          code = 'REFUND_TOO_LARGE';
          message = `refund amount ${command.amountCents} exceeds outstanding ${this.#paidCents - this.#refundedCents}`;
        }
        break;
      }
      case 'pack':
      case 'deliver':
        // These have no additional field requirements
        break;
    }

    if (code) {
      const entry = {
        seq: this.#audit.length + 1,
        commandId: command.commandId,
        type: command.type,
        at: auditAt,
        from: this.#state,
        to: this.#state,
        ok: false,
        code,
      };
      this.#audit.push(entry);

      const result = {
        ok: false,
        code,
        message: message || code,
        state: this.#state,
        seq: entry.seq,
        replayed: false,
      };
      this.#commandIds.set(command.commandId, result);
      return result;
    }

    // Handle clock regression if we get here
    if (command.at < this.#clockMs - auditAt) {
      const entry = {
        seq: this.#audit.length + 1,
        commandId: command.commandId,
        type: command.type,
        at: auditAt,
        from: this.#state,
        to: this.#state,
        ok: false,
        code: 'CLOCK_REGRESSION',
      };
      this.#audit.push(entry);

      const result = {
        ok: false,
        code: 'CLOCK_REGRESSION',
        message: `command timestamp ${command.at} is earlier than clock ${this.#clockMs}`,
        state: this.#state,
        seq: entry.seq,
        replayed: false,
      };
      this.#commandIds.set(command.commandId, result);
      return result;
    }

    // Apply the command
    let newState = this.#state;

    switch (command.type) {
      case 'addItem':
        this.#items.set(command.sku, {
          sku: command.sku,
          qty: command.qty,
          unitPriceCents: command.unitPriceCents,
        });
        break;
      case 'removeItem':
        this.#items.delete(command.sku);
        break;
      case 'pay':
        this.#paidCents = command.amountCents;
        newState = 'paid';
        break;
      case 'pack':
        newState = 'packed';
        break;
      case 'ship':
        this.#shipment = {
          carrier: command.carrier,
          tracking: command.tracking,
        };
        newState = 'shipped';
        break;
      case 'deliver':
        this.#deliveredAt = command.at;
        newState = 'delivered';
        break;
      case 'cancel':
        this.#refundedCents = this.#paidCents;
        newState = 'cancelled';
        break;
      case 'refund':
        this.#refundedCents += command.amountCents;
        if (this.#refundedCents === this.#paidCents) {
          newState = 'refunded';
        }
        break;
    }

    this.#state = newState;

    const entry = {
      seq: this.#audit.length + 1,
      commandId: command.commandId,
      type: command.type,
      at: auditAt,
      from: this.#state === newState ? newState : newState,
      to: newState,
      ok: true,
    };

    // Calculate from correctly
    entry.from = this.#audit.length === 0 ? 'created' : this.#audit[this.#audit.length - 1].to;
    if (newState === this.#state) {
      // State didn't change, so from should be the current state before this change
      if (command.type === 'addItem' || command.type === 'removeItem') {
        entry.from = 'created';
      }
    }

    this.#audit.push(entry);

    const result = {
      ok: true,
      state: newState,
      seq: entry.seq,
      replayed: false,
    };
    this.#commandIds.set(command.commandId, result);
    return result;
  }"}

