/** An order and everything that has been asked of it. */
export class Order {
  #id;

  #state = 'created';

  #items = new Map();

  #paidCents = 0;

  #refundedCents = 0;

  #clockMs;

  #audit = [];

  #shipment = null;

  #deliveredAt = null;

  #commandIds = new Map();

  /**
   * @param {{id: string, createdAt?: number}} init Identity and start time.
   */
