    if (typeof init !== 'object' || init === null) throw new TypeError('init must be an object');
    if (typeof init.id !== 'string' || init.id === '') throw new TypeError('init.id must be a non-empty string');
    const createdAt = init.createdAt === undefined ? 0 : init.createdAt;
    if (!Number.isInteger(createdAt) || createdAt < 0) {
      throw new TypeError('init.createdAt must be a non-negative integer');
    }
    this.#id = init.id;
    this.#clockMs = createdAt;
  }

  /** @returns {string} Order identity. */
  get id() {
    return this.#id;
  }

  /** @returns {string} Current state. */
  get state() {
    return this.#state;
  }

  /** @returns {Array<{sku: string, qty: number, unitPriceCents: number}>} Items in ascending sku order. */
  get items() {
    return [...this.#items.keys()].sort().map((sku) => ({ ...this.#items.get(sku) }));
  }

  /** @returns {number} Sum of quantity times unit price over all items. */
  get totalCents() {
    let total = 0;
    for (const item of this.#items.values()) total += item.qty * item.unitPriceCents;
    return total;
  }

  /** @returns {number} Amount captured by a successful payment. */
  get paidCents() {
    return this.#paidCents;
  }

  /** @returns {number} Amount refunded so far. */
  get refundedCents() {
    return this.#refundedCents;
  }

  /** @returns {number} High-water mark of command timestamps. */
  get clockMs() {
    return this.#clockMs;
  }

  /** @returns {object[]} Copy of the audit trail, oldest first. */
  get audit() {
    return this.#audit.map((entry) => ({ ...entry }));
  }

  /** @returns {{carrier: string, tracking: string}|null} Shipment details once shipped. */
  get shipment() {
    return this.#shipment === null ? null : { ...this.#shipment };
  }

  /** @returns {number|null} Timestamp of delivery, once delivered. */
  get deliveredAt() {
    return this.#deliveredAt;
  }

  /** @returns {object} Plain description of the order's visible state. */
  snapshot() {
    return {
      id: this.#id,
      state: this.#state,
      items: this.items,
      totalCents: this.totalCents,
      paidCents: this.#paidCents,
      refundedCents: this.#refundedCents,
      clockMs: this.#clockMs,
      seq: this.#audit.length,
    };
  }

  /**
   * Apply one command.
   *
   * @param {object} command Command to apply.
   * @returns {{ok: boolean, state: string, seq: number, replayed: boolean, code?: string, message?: string}} Outcome.
   */
  apply(command) {
    // Structural validation - throw on failure
    if (typeof command !== 'object' || command === null) {
      throw new TypeError('command must be an object');
    }

    if (!COMMAND_TYPES.includes(command.type)) {
      throw new TypeError(`unknown command type: ${command.type}`);
    }

    if (typeof command.commandId !== 'string' || command.commandId === '') {
      throw new TypeError('command must carry a non-empty commandId');
    }

    if (!Number.isInteger(command.at) || command.at < 0) {
      throw new TypeError('command must carry a non-negative integer at');
    }

    // Check for replayed commandId
    if (this.#commandIds.has(command.commandId)) {
      const recorded = this.#commandIds.get(command.commandId);
      return {
        ...recorded,
        replayed: true,
      };
    }

    // Determine audit timestamp and update clock
    let auditAt;
    if (command.at < this.#clockMs) {
      auditAt = this.#clockMs; // Stamp with current clock on regression
    } else {
      auditAt = command.at;
      this.#clockMs = command.at;
    }

    // Record the from state
    const fromState = this.#state;
    let toState = fromState; // Default to no state change
    let code = null;
    let message = null;

    // Clock check - always first in the guard chain
    if (command.at < this.#clockMs) {
      code = 'CLOCK_REGRESSION';
    }

    // State check
    if (code === null && !allowedTypes(fromState).includes(command.type)) {
      code = 'BAD_STATE';
    }

    // Field and business logic checks
    if (code === null) {
      switch (command.type) {
        case 'addItem': {
          if (typeof command.sku !== 'string' || command.sku === '') {
            code = 'MISSING_FIELD';
          } else if (!Number.isInteger(command.qty) || command.qty < 1) {
            code = 'BAD_AMOUNT';
          } else if (!Number.isInteger(command.unitPriceCents) || command.unitPriceCents < 0) {
            code = 'BAD_AMOUNT';
          } else if (this.#items.has(command.sku)) {
            code = 'DUPLICATE_SKU';
          }
          break;
        }
        case 'removeItem': {
          if (typeof command.sku !== 'string' || command.sku === '') {
            code = 'MISSING_FIELD';
          } else if (!this.#items.has(command.sku)) {
            code = 'NO_SUCH_ITEM';
          }
          break;
        }
        case 'pay': {
          if (!Number.isInteger(command.amountCents) || command.amountCents < 0) {
            code = 'BAD_AMOUNT';
          } else if (this.totalCents === 0 && command.amountCents === 0) {
            code = 'EMPTY_ORDER';
          } else if (command.amountCents !== this.totalCents) {
            code = 'AMOUNT_MISMATCH';
          }
          break;
        }
        case 'ship': {
          if (typeof command.carrier !== 'string' || command.carrier === '') {
            code = 'MISSING_FIELD';
          } else if (typeof command.tracking !== 'string' || command.tracking === '') {
            code = 'MISSING_FIELD';
          }
          break;
        }
        case 'cancel': {
          if (typeof command.reason !== 'string' || command.reason === '') {
            code = 'MISSING_FIELD';
          }
          break;
        }
        case 'refund': {
          if (!Number.isInteger(command.amountCents) || command.amountCents < 1) {
            code = 'BAD_AMOUNT';
          } else if (command.amountCents > this.#paidCents - this.#refundedCents) {
            code = 'REFUND_TOO_LARGE';
          }
          break;
        }
        case 'pack':
        case 'deliver':
          // No additional field requirements
          break;
      }
    }

    // Apply command if all checks passed
    if (code === null) {
      switch (command.type) {
        case 'addItem':
          this.#items.set(command.sku, {
            sku: command.sku,
            qty: command.qty,
            unitPriceCents: command.unitPriceCents,
          });
          toState = 'created';
          break;
        case 'removeItem':
          this.#items.delete(command.sku);
          toState = 'created';
          break;
        case 'pay':
          this.#paidCents = command.amountCents;
          toState = 'paid';
          break;
        case 'pack':
          toState = 'packed';
          break;
        case 'ship':
          this.#shipment = {
            carrier: command.carrier,
            tracking: command.tracking,
          };
          toState = 'shipped';
          break;
        case 'deliver':
          this.#deliveredAt = command.at;
          toState = 'delivered';
          break;
        case 'cancel':
          this.#refundedCents = this.#paidCents;
          toState = 'cancelled';
          break;
        case 'refund':
          this.#refundedCents += command.amountCents;
          if (this.#refundedCents === this.#paidCents) {
            toState = 'refunded';
          } else {
            toState = 'delivered';
          }
          break;
      }
      this.#state = toState;
    }

    // Create audit entry
    const entry = {
      seq: this.#audit.length + 1,
      commandId: command.commandId,
      type: command.type,
      at: auditAt,
      from: fromState,
      to: toState,
      ok: code === null,
    };
    if (code !== null) {
      entry.code = code;
    }

    this.#audit.push(entry);

    // Create and store result
    let resultMessage = null;
    if (code !== null) {
      switch (code) {
        case 'CLOCK_REGRESSION':
          resultMessage = `command timestamp ${command.at} is earlier than clock ${this.#clockMs}`;
          break;
        case 'BAD_STATE':
          resultMessage = `state ${fromState} does not allow ${command.type}`;
          break;
        case 'MISSING_FIELD':
          resultMessage = `command missing required field`;
          break;
        case 'BAD_AMOUNT':
          resultMessage = `command has invalid amount`;
          break;
        case 'DUPLICATE_SKU':
          resultMessage = `sku is already in the order`;
          break;
        case 'NO_SUCH_ITEM':
          resultMessage = `sku is not in the order`;
          break;
        case 'EMPTY_ORDER':
          resultMessage = `cannot pay for an empty order`;
          break;
        case 'AMOUNT_MISMATCH':
          resultMessage = `payment amount does not match order total`;
          break;
        case 'REFUND_TOO_LARGE':
          resultMessage = `refund amount exceeds outstanding balance`;
          break;
        default:
          resultMessage = code;
      }
    }

    const result = {
      ok: code === null,
      state: code === null ? toState : fromState,
      seq: entry.seq,
      replayed: false,
    };
    if (code !== null) {
      result.code = code;
      result.message = resultMessage;
    }

    this.#commandIds.set(command.commandId, result);
    return result;
  }

  /**
   * Build an order by applying a command list in order.
   *
   * @param {{id: string, createdAt?: number}} init Identity and start time.
   * @param {object[]} commands Commands to apply.
   * @returns {Order} The resulting order.
   */
  static replay(init, commands) {
    if (!Array.isArray(commands)) {
      throw new TypeError();
    }
    const order = new Order(init);
    for (const command of commands) {
      order.apply(command);
    }
    return order;
  }
}
