   * @returns {Order} The resulting order.
   */
  static replay(init, commands) {
    if (!Array.isArray(commands)) {
      throw new TypeError();
    }
    const order = new Order(init);
    for (const command of commands) {
      order.apply(command);
    }
    return order;
